INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'body language', 'n.', '/ˈbɒdi læŋɡwɪdʒ/', '肢体语言;身势语', 'We can learn a lot by reading other people''s body language.', '通过解读他人的肢体语言,我们能了解很多。', 'Body Language', 1, 0, 'senior', 'wordlist', 'elective1', 'U4', 'read body language', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'gesture', 'n.', '/ˈdʒestʃə(r)/', '手势;姿势;姿态', 'A wave of the hand is a common gesture for saying goodbye.', '挥手是一种常见的表示再见的手势。', 'Body Language', 2, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a friendly gesture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'nonverbal', 'adj.', '/ˌnɒnˈvɜːbl/', '不涉及言语的;非言语的', 'Most nonverbal messages are sent through our face and hands.', '大多数非言语信息通过我们的面部和双手传递。', 'Body Language', 3, 0, 'senior', 'wordlist', 'elective1', 'U4', 'nonverbal communication', '美音 /ˌnɑːnˈvɜːrbl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'interaction', 'n.', '/ˌɪntərˈækʃn/', '交流;相互影响', 'Body language plays a big part in our daily interaction with others.', '肢体语言在我们与他人的日常交流中作用很大。', 'Body Language', 4, 0, 'senior', 'wordlist', 'elective1', 'U4', 'social interaction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'interpret', 'v.', '/ɪnˈtɜːprɪt/', '把……理解(解释)为;口译', 'People from different cultures may interpret the same gesture in different ways.', '不同文化的人可能会以不同方式理解同一个手势。', 'Body Language', 5, 0, 'senior', 'wordlist', 'elective1', 'U4', 'interpret a gesture', '美音 /ɪnˈtɜːrprɪt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'demonstrate', 'v.', '/ˈdemənstreɪt/', '表现;表达;说明;证明', 'In Japan, looking down can demonstrate respect to an older person.', '在日本,低头看可以向长者表达尊重。', 'Body Language', 6, 0, 'senior', 'wordlist', 'elective1', 'U4', 'demonstrate respect', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'demonstration', 'n.', '/ˌdemənˈstreɪʃn/', '示范;表露;证明', 'A warm hug is a clear demonstration of friendship in many cultures.', '在许多文化中,热情的拥抱是友谊的明确表露。', 'Body Language', 7, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a demonstration of feelings', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'differ', 'v.', '/ˈdɪfə(r)/', '相异;不同于', 'The gestures for "yes" and "no" differ around the world.', '表示"是"和"不是"的手势在世界各地各不相同。', 'Body Language', 8, 0, 'senior', 'wordlist', 'elective1', 'U4', 'differ from culture to culture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'distinguish', 'v.', '/dɪˈstɪŋɡwɪʃ/', '区分;辨别', 'It is hard to distinguish a real smile from a fake one.', '很难把真笑和假笑区分开来。', 'Body Language', 9, 0, 'senior', 'wordlist', 'elective1', 'U4', 'distinguish A from B', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'distract', 'v.', '/dɪˈstrækt/', '分散(注意力);使分心', 'A loud phone can easily distract students from the lesson.', '响亮的手机声很容易使学生从课上分心。', 'Body Language', 10, 0, 'senior', 'wordlist', 'elective1', 'U4', 'distract sb from', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'perceive', 'v.', '/pəˈsiːv/', '察觉;看待;理解', 'A good teacher can perceive when students are bored or worried.', '好老师能察觉到学生何时感到无聊或担忧。', 'Body Language', 11, 0, 'senior', 'wordlist', 'elective1', 'U4', 'perceive a feeling', '美音 /pərˈsiːv/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'reveal', 'v.', '/rɪˈviːl/', '揭示;显示;露出', 'Your face often reveals your true feelings before you speak.', '在你开口之前,你的脸常常已经显露了真实感受。', 'Body Language', 12, 0, 'senior', 'wordlist', 'elective1', 'U4', 'reveal one''s feelings', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'imply', 'v.', '/ɪmˈplaɪ/', '意味着;暗示', 'Crossing your arms may imply that you do not agree.', '双臂交叉可能暗示你并不同意。', 'Body Language', 13, 0, 'senior', 'wordlist', 'elective1', 'U4', 'imply that', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'infer', 'v.', '/ɪnˈfɜː(r)/', '推断;推理', 'From her red eyes we could infer that she had been crying.', '从她通红的眼睛我们能推断出她一直在哭。', 'Body Language', 14, 0, 'senior', 'wordlist', 'elective1', 'U4', 'infer the meaning', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'inference', 'n.', '/ˈɪnfərəns/', '推断的结果;结论;推论', 'We make inferences about feelings from people''s body language.', '我们根据人们的肢体语言对其感受作出推断。', 'Body Language', 15, 0, 'senior', 'wordlist', 'elective1', 'U4', 'make an inference', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'stare', 'v.', '/steə(r)/', '盯着看;凝视', 'Staring at someone too long can be interpreted as a threat.', '盯着别人看太久可能被理解为一种威胁。', 'Body Language', 16, 0, 'senior', 'wordlist', 'elective1', 'U4', 'stare at sb', '美音 /ster/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'bow', 'v.', '/baʊ/', '鞠躬;点头', 'In some countries people bow from the waist when they meet.', '在一些国家,人们见面时会从腰部鞠躬。', 'Body Language', 17, 0, 'senior', 'wordlist', 'elective1', 'U4', 'bow from the waist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'bend', 'v.', '/bend/', '(使)弯曲;倾斜;偏向', 'We bend our head forward as a sign of respect or shame.', '我们把头向前低下,以示尊重或羞愧。', 'Body Language', 18, 0, 'senior', 'wordlist', 'elective1', 'U4', 'bend forward', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'slump', 'v.', '/slʌmp/', '垂头弯腰地走(或坐等)', 'When we feel powerless, we tend to slump and make ourselves smaller.', '当我们感到无力时,往往会垂头弯腰,让自己显得更小。', 'Body Language', 19, 0, 'senior', 'wordlist', 'elective1', 'U4', 'slump in a chair', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'pose', 'n.', '/pəʊz/', '姿势;故作姿态', 'Holding a powerful pose for a while may make you feel stronger.', '保持有力的姿势一会儿,可能会让你感觉更强大。', 'Body Language', 20, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a powerful pose', '美音 /poʊz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'react', 'v.', '/riˈækt/', '(对……)起反应;回应', 'A good teacher knows how to react to students'' body language.', '好老师懂得如何对学生的肢体语言作出回应。', 'Body Language', 21, 0, 'senior', 'wordlist', 'elective1', 'U4', 'react to body language', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'embarrassed', 'adj.', '/ɪmˈbærəst/', '难堪的;尴尬的', 'Some students hide their faces in their hands when they feel embarrassed.', '有些学生感到尴尬时会用双手捂住脸。', 'Body Language', 22, 0, 'senior', 'wordlist', 'elective1', 'U4', 'feel embarrassed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'fake', 'adj.', '/feɪk/', '假装的;假的;冒充的', 'A fake smile is often used to hide anger or worry.', '假笑常被用来掩饰愤怒或担忧。', 'Body Language', 23, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a fake smile', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'reliable', 'adj.', '/rɪˈlaɪəbl/', '可靠的;可信赖的', 'Body language can be a more reliable guide to feelings than words.', '肢体语言可能比言语更能可靠地反映感受。', 'Body Language', 24, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a reliable guide', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'identical', 'adj.', '/aɪˈdentɪkl/', '相同的', 'An identical gesture may carry a different meaning in another country.', '相同的手势在另一个国家可能含义不同。', 'Body Language', 25, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an identical gesture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'internal', 'adj.', '/ɪnˈtɜːnl/', '内部的;里面的', 'Our body language is shaped by our internal thoughts and feelings.', '我们的肢体语言受内在想法和感受的影响。', 'Body Language', 26, 0, 'senior', 'wordlist', 'elective1', 'U4', 'internal feelings', '美音 /ɪnˈtɜːrnl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'slight', 'adj.', '/slaɪt/', '轻微的;略微的;细小的', 'Even a slight frown on her face can tell us she is unhappy.', '她脸上哪怕一丝轻微的皱眉也能告诉我们她不开心。', 'Body Language', 27, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a slight frown', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'slightly', 'adv.', '/ˈslaɪtli/', '略微;稍微', 'Interested students often lean slightly forward towards the teacher.', '感兴趣的学生常常稍微向老师前倾。', 'Body Language', 28, 0, 'senior', 'wordlist', 'elective1', 'U4', 'lean slightly forward', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'merely', 'adv.', '/ˈmɪəli/', '只是;仅仅;只不过', 'Some students cross their arms merely because they feel cold.', '有些学生交叉双臂只不过是因为觉得冷。', 'Body Language', 29, 0, 'senior', 'wordlist', 'elective1', 'U4', 'merely because', '美音 /ˈmɪrli/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'ultimately', 'adv.', '/ˈʌltɪmətli/', '最终;最后', 'Reading body language ultimately helps a teacher support every student.', '解读肢体语言最终能帮助老师支持每一个学生。', 'Body Language', 30, 0, 'senior', 'wordlist', 'elective1', 'U4', 'ultimately help', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'vary', 'v.', '/ˈveəri/', '(根据情况)变化;改变', 'Like spoken language, body language varies from culture to culture.', '和口语一样,肢体语言因文化不同而各异。', 'Body Language', 31, 0, 'senior', 'wordlist', 'elective1', 'U4', 'vary from culture to culture', '美音 /ˈveri/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'tendency', 'n.', '/ˈtendənsi/', '趋势;倾向', 'People have a tendency to lean towards whatever interests them.', '人们倾向于向任何让自己感兴趣的事物靠近。', 'Body Language', 32, 0, 'senior', 'wordlist', 'elective1', 'U4', 'have a tendency to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'tone', 'n.', '/təʊn/', '语气;腔调;口吻', 'Tone of voice, like body language, carries part of our message.', '语气和肢体语言一样,承载着我们一部分信息。', 'Body Language', 33, 0, 'senior', 'wordlist', 'elective1', 'U4', 'tone of voice', '美音 /toʊn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'component', 'n.', '/kəmˈpəʊnənt/', '组成部分;零件', 'Reacting to body language is an important component of teaching.', '对肢体语言作出回应是教学的一个重要组成部分。', 'Body Language', 34, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an important component', '美音 /kəmˈpoʊnənt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'occupy', 'v.', '/ˈɒkjupaɪ/', '占据;占用', 'Some students occupy themselves by staring out of the window.', '有些学生靠盯着窗外打发时间。', 'Body Language', 35, 0, 'senior', 'wordlist', 'elective1', 'U4', 'occupy oneself', '美音 /ˈɑːkjupaɪ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'clarify', 'v.', '/ˈklærəfaɪ/', '使更清晰易懂;阐明;澄清', 'We can ask questions to clarify any misunderstanding about a gesture.', '我们可以提问来澄清关于某个手势的任何误解。', 'Body Language', 36, 0, 'senior', 'wordlist', 'elective1', 'U4', 'clarify a misunderstanding', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'inquire', 'v.', '/ɪnˈkwaɪə(r)/', '询问;打听', 'If a student looks upset, the teacher may inquire what is wrong.', '如果学生看起来心烦,老师可能会询问出了什么事。', 'Body Language', 37, 0, 'senior', 'wordlist', 'elective1', 'U4', 'inquire about', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'intervene', 'v.', '/ˌɪntəˈviːn/', '干预;介入', 'Body language tells a teacher when to intervene and offer help.', '肢体语言会告诉老师何时介入并提供帮助。', 'Body Language', 38, 0, 'senior', 'wordlist', 'elective1', 'U4', 'intervene in time', '美音 /ˌɪntərˈviːn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'employ', 'v.', '/ɪmˈplɔɪ/', '使用;应用;雇用', 'Someone who employs the "OK" gesture in Japan may mean money.', '在日本使用"OK"手势的人可能指的是钱。', 'Body Language', 39, 0, 'senior', 'wordlist', 'elective1', 'U4', 'employ a gesture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'favour', 'v.', '/ˈfeɪvə(r)/', '较喜欢;选择;有利于', 'In many places people favour shaking hands when they meet.', '在许多地方,人们见面时更喜欢握手。', 'Body Language', 40, 0, 'senior', 'wordlist', 'elective1', 'U4', 'favour shaking hands', '美式拼 favor;美音 /ˈfeɪvər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'witness', 'v.', '/ˈwɪtnəs/', '当场看到;目击;见证', 'Someone who witnesses this gesture in France may read it as zero.', '在法国看到这个手势的人可能把它理解为零。', 'Body Language', 41, 0, 'senior', 'wordlist', 'elective1', 'U4', 'witness a scene', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cheek', 'n.', '/tʃiːk/', '面颊;脸颊', 'In France and Russia friends may kiss each other on the cheek.', '在法国和俄罗斯,朋友见面可能互相亲吻脸颊。', 'Body Language', 42, 0, 'senior', 'wordlist', 'elective1', 'U4', 'kiss on the cheek', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'chest', 'n.', '/tʃest/', '胸部;胸膛', 'Worried students may have their arms crossed in front of their chests.', '焦虑的学生可能双臂交叉抱在胸前。', 'Body Language', 43, 0, 'senior', 'wordlist', 'elective1', 'U4', 'arms across the chest', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'chin', 'n.', '/tʃɪn/', '下巴', 'With their chins on their hands, daydreamers stare out of the window.', '下巴托在手上,爱做白日梦的人盯着窗外发呆。', 'Body Language', 44, 0, 'senior', 'wordlist', 'elective1', 'U4', 'chin on hands', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'waist', 'n.', '/weɪst/', '腰;腰部', 'Bowing from the waist is a polite greeting in many places.', '从腰部鞠躬在许多地方是一种礼貌的问候。', 'Body Language', 45, 0, 'senior', 'wordlist', 'elective1', 'U4', 'from the waist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'weep', 'v.', '/wiːp/', '哭泣;流泪', 'If a student''s eyes are red from weeping, deeper problems may exist.', '如果学生的眼睛因哭泣而通红,可能存在更深的问题。', 'Body Language', 46, 0, 'senior', 'wordlist', 'elective1', 'U4', 'weep quietly', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'educator', 'n.', '/ˈedʒukeɪtə(r)/', '教师;教育工作者', 'As an educator, I read my students'' minds through their body language.', '作为一名教育工作者,我通过学生的肢体语言读懂他们的心思。', 'Body Language', 47, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an experienced educator', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'in other words', 'phr.', '/ɪn ˈʌðə wɜːdz/', '换句话说;也就是说', 'He avoided eye contact; in other words, he felt nervous.', '他回避眼神接触;换句话说,他感到紧张。', 'Body Language', 48, 0, 'senior', 'wordlist', 'elective1', 'U4', 'in other words', '美音 /ɪn ˈʌðər wɜːrdz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'by contrast', 'phr.', '/baɪ ˈkɒntrɑːst/', '相比之下', 'Some people make long eye contact; by contrast, others avoid it.', '有些人会长时间对视;相比之下,另一些人则回避它。', 'Body Language', 49, 0, 'senior', 'wordlist', 'elective1', 'U4', 'by contrast', '美音 /baɪ ˈkɑːntræst/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'break down', 'phr.', '/breɪk daʊn/', '消除;打破;分解', 'A warm smile can break down barriers between strangers.', '温暖的微笑能打破陌生人之间的隔阂。', 'Body Language', 50, 0, 'senior', 'wordlist', 'elective1', 'U4', 'break down barriers', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u4.01', '①动名词作动词宾语(enjoy/finish/mind/avoid/keep/practise/suggest/consider/imagine/can''t help + doing)', 'A2', 11, '选择性必修一 U4 — 某些动词后只能接动名词作宾语:enjoy, finish, mind, avoid, keep, practise, suggest, consider, imagine, can''t help, give up, miss 等 + doing;不接不定式或原形。', 1, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u4.02', '②动名词作介词宾语(be good at / look forward to / be used to / be interested in / instead of / thank sb for + doing)', 'A2', 11, '选择性必修一 U4 — 介词后接动名词作其宾语:at/to/in/of/for/about/on 等介词(含 look forward to, be/get used to, instead of, thank sb for)+ doing。', 2, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u4.03', '③动名词作表语(My job is teaching. / Seeing is believing.)', 'A2', 11, '选择性必修一 U4 — 系动词 be 后用动名词作表语,说明主语的内容/性质(My job is teaching.);区别于不定式作表语和现在分词作定语/状语。', 3, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'She enjoys ____ about body language in different cultures.', 'learning', 'to learn', 'learn', 'learned', 'A', 'enjoy 后只接动名词作宾语 → learning。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'You should avoid ____ this "OK" gesture in Brazil, as it is not polite.', 'to make', 'making', 'make', 'made', 'B', 'avoid 后接动名词 → making。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'When she felt embarrassed, she could not help ____ her face in her hands.', 'to hide', 'hide', 'hiding', 'hidden', 'C', 'can''t help 后接动名词 → hiding。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Experts suggest ____ at yourself in the mirror to feel happier.', 'to smile', 'smile', 'smiled', 'smiling', 'D', 'suggest 后接动名词 → smiling。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'The shy student kept ____ eye contact with the teacher.', 'avoiding', 'to avoid', 'avoid', 'avoided', 'A', 'keep 后接动名词 → avoiding。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Would you mind ____ your hand circles over your stomach to show "I''m full"?', 'to move', 'moving', 'move', 'moved', 'B', 'mind 后接动名词 → moving。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Actors practise ____ feelings with only their faces and hands.', 'to show', 'show', 'showing', 'shown', 'C', 'practise 后接动名词 → showing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Have you finished ____ the table about gestures on page 39?', 'to fill', 'fill', 'filled', 'filling', 'D', 'finish 后接动名词 → filling。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Please imagine ____ someone too long; it can feel like a threat.', 'staring at', 'to stare at', 'stare at', 'stared at', 'A', 'imagine 后接动名词 → staring at。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'The teacher considered ____ class activities to suit shy students.', 'to change', 'changing', 'change', 'changed', 'B', 'consider 后接动名词 → changing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Some students enjoy ____ out of the window while daydreaming.', 'to stare', 'stare', 'staring', 'stared', 'C', 'enjoy 后接动名词 → staring。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'He never gives up ____ to read people''s faces correctly.', 'to try', 'try', 'tried', 'trying', 'D', 'give up 后接动名词 → trying。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Avoid ____ your arms in front of your chest if you want to look open.', 'crossing', 'to cross', 'cross', 'crossed', 'A', 'avoid 后接动名词 → crossing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'When we feel proud, we can''t help ____ ourselves to look bigger.', 'to straighten', 'straightening', 'straighten', 'straightened', 'B', 'can''t help 后接动名词 → straightening。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'She kept ____ slightly forward to show she was interested.', 'to lean', 'lean', 'leaning', 'leaned', 'C', 'keep 后接动名词 → leaning。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'I really miss ____ my friends nod and smile when we talk.', 'to see', 'see', 'seen', 'seeing', 'D', 'miss 后接动名词 → seeing。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Would you mind ____ down a little when you greet the elder?', 'bowing', 'to bow', 'bow', 'bowed', 'A', 'mind 后接动名词 → bowing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'The teacher suggested ____ distracted students that they pay attention.', 'to remind', 'reminding', 'remind', 'reminded', 'B', 'suggest 后接动名词 → reminding。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'He practised ____ his face calm so others could not read his feelings.', 'to keep', 'keep', 'keeping', 'kept', 'C', 'practise 后接动名词 → keeping。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.01'), 'Powerful people often consider ____ a confident pose before a speech.', 'to hold', 'hold', 'held', 'holding', 'D', 'consider 后接动名词 → holding。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'She is good at ____ what people feel from their faces.', 'reading', 'to read', 'read', 'readen', 'A', 'be good at 后接动名词作介词宾语 → reading。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'We look forward to ____ how body language differs around the world.', 'to learn', 'learning', 'learn', 'learned', 'B', 'look forward to 中 to 是介词,后接动名词 → learning。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'In Japan, you can show respect instead of ____ straight into an elder''s eyes.', 'to look', 'look', 'looking', 'looked', 'C', 'instead of 后接动名词 → looking。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'Many international students are interested in ____ Chinese gestures.', 'to understand', 'understand', 'understood', 'understanding', 'D', 'be interested in 后接动名词 → understanding。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'After years abroad, he is used to ____ hands when he meets someone.', 'shaking', 'to shake', 'shake', 'shaken', 'A', 'be used to(习惯于)中 to 是介词,后接动名词 → shaking。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'Thank you for ____ me how to read a fake smile.', 'to teach', 'teaching', 'teach', 'taught', 'B', 'thank sb for 后接动名词 → teaching。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'A smile is a simple way of ____ down barriers between strangers.', 'to break', 'break', 'breaking', 'broken', 'C', 'way of 后接动名词 → breaking。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'She apologised by ____ her head and lowering her eyes.', 'to bow', 'bow', 'bowed', 'bowing', 'D', '介词 by 后接动名词 → bowing。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'He kept silent for a while before ____ his real feelings.', 'revealing', 'to reveal', 'reveal', 'revealed', 'A', '介词 before 后接动名词 → revealing。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'We learn about feelings by ____ at people''s gestures and faces.', 'to look', 'looking', 'look', 'looked', 'B', '介词 by 后接动名词 → looking。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'They are good at ____ a real smile from a fake one.', 'to distinguish', 'distinguish', 'distinguishing', 'distinguished', 'C', 'be good at 后接动名词 → distinguishing。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'She is interested in ____ how Chinese people use body language.', 'to learn', 'learn', 'learned', 'learning', 'D', 'be interested in 后接动名词 → learning。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'Instead of ____, the worried student crossed his arms tightly.', 'relaxing', 'to relax', 'relax', 'relaxed', 'A', 'instead of 后接动名词 → relaxing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'Our teacher is used to ____ when we are interested or bored.', 'to notice', 'noticing', 'notice', 'noticed', 'B', 'be used to(习惯于)后接动名词 → noticing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'He got through the difficult talk by ____ at himself in the mirror first.', 'to smile', 'smile', 'smiling', 'smiled', 'C', '介词 by 后接动名词 → smiling。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'We look forward to ____ the art of non-verbal humour in the film.', 'to appreciate', 'appreciate', 'appreciated', 'appreciating', 'D', 'look forward to 后接动名词 → appreciating。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'Thank you for ____ me the difference between these two gestures.', 'showing', 'to show', 'show', 'shown', 'A', 'thank sb for 后接动名词 → showing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'She is good at ____ what each pose is telling us.', 'to interpret', 'interpreting', 'interpret', 'interpreted', 'B', 'be good at 后接动名词 → interpreting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'He showed respect by ____ his head when talking to the old man.', 'to lower', 'lower', 'lowering', 'lowered', 'C', '介词 by 后接动名词 → lowering。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.02'), 'Instead of ____, she chose to nod and let her body do the talking.', 'to speak', 'speak', 'spoken', 'speaking', 'D', 'instead of 后接动名词 → speaking。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'The crucial thing is ____ body language in a way that suits the culture.', 'using', 'to using', 'use', 'used', 'A', 'be 后用动名词作表语,说明主语 the thing 的内容 → using。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'His job is ____ sign language to deaf children.', 'to teaching', 'teaching', 'teach', 'taught', 'B', '动名词作表语,说明 his job 是什么 → teaching。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'Seeing is ____; we trust what a person''s face shows us.', 'to believe', 'believe', 'believing', 'believed', 'C', '动名词作表语(Seeing is believing 谚语)→ believing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'One good way of saying "I''m full" is ____ your hand over your stomach.', 'to moving', 'move', 'moved', 'moving', 'D', '动名词作表语,说明 the way 是什么 → moving。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'The main thing is ____ distracted students that they need to focus.', 'reminding', 'to reminding', 'remind', 'reminded', 'A', '动名词作表语 → reminding。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'My duty as a teacher is ____ every student to learn well.', 'to helping', 'helping', 'help', 'helped', 'B', '动名词作表语,说明 my duty 的内容 → helping。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'The theme of his presentation is ____ down barriers between groups.', 'to breaking', 'break', 'breaking', 'broken', 'C', '动名词作表语 → breaking。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'Her favourite activity in class is ____ out of the window.', 'to staring', 'stare', 'stared', 'staring', 'D', '动名词作表语,说明 activity 的内容 → staring。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'What a smile can do is ____ us through difficult situations.', 'helping', 'to helping', 'help', 'helped', 'A', '动名词作表语 → helping。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'The best example of useful body language is ____ at others.', 'to smiling', 'smiling', 'smile', 'smiled', 'B', '动名词作表语 → smiling。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'A teacher''s real skill is ____ when a student is troubled.', 'to perceiving', 'perceive', 'perceiving', 'perceived', 'C', '动名词作表语,说明 skill 的内容 → perceiving。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'One sign of being proud is ____ up to make yourself look bigger.', 'to straightening', 'straighten', 'straightened', 'straightening', 'D', '动名词作表语 → straightening。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'The hardest part of the job is ____ when students are really troubled.', 'distinguishing', 'to distinguishing', 'distinguish', 'distinguished', 'A', '动名词作表语 → distinguishing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'What worried students often do is ____ their arms in front of them.', 'to crossing', 'crossing', 'cross', 'crossed', 'B', '动名词作表语 → crossing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'A polite greeting in Japan is ____ from the waist.', 'to bowing', 'bow', 'bowing', 'bowed', 'C', '动名词作表语 → bowing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'His habit when bored is ____ his chin on his hand.', 'to resting', 'rest', 'rested', 'resting', 'D', '动名词作表语 → resting。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'The first step in reading people is ____ at their faces carefully.', 'looking', 'to looking', 'look', 'looked', 'A', '动名词作表语 → looking。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'A common way to say "sleep" is ____ your hands by your head.', 'to placing', 'placing', 'place', 'placed', 'B', '动名词作表语 → placing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'Her real talent is ____ a fake smile in a single second.', 'to spotting', 'spot', 'spotting', 'spotted', 'C', '动名词作表语 → spotting。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U4' AND code='e1u4.03'), 'The point of the lesson is ____ feelings without using any words.', 'to expressing', 'express', 'expressed', 'expressing', 'D', '动名词作表语 → expressing。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Listening to How Bodies Talk', 'We use both words and body language to express our thoughts in our interactions with other people. We can learn a lot about what people are thinking by watching their body language. Words are important, but the way people stand, hold their arms and move their hands can also give us information about their feelings. Just like spoken language, body language varies from culture to culture. The crucial thing is using body language in a way that is appropriate to the culture you are in. A gesture that is friendly in one country may be rude in another. Because of this, a clever traveller pays attention not only to what people say, but also to how they stand, move and look. In other words, learning to read bodies is just as useful as learning new words, and sometimes it tells us even more than speech does.', 'Body Language', 146, '[{"q":"What does the passage say body language can tell us?","answer":"A","options":["Information about people''s feelings.","The exact words people will say.","How rich a person is.","Where a person was born."],"explanation":"原文 ''give us information about their feelings'' 的转述。"},{"q":"Why must travellers be careful with gestures?","answer":"B","options":["Gestures are always the same everywhere.","A gesture may be friendly in one place but rude in another.","Gestures have no meaning at all.","Only words can be misunderstood."],"explanation":"原文 ''A gesture that is friendly in one country may be rude in another'' 的转述。"},{"q":"What is the writer''s main point at the end?","answer":"A","options":["Reading bodies can be as useful as learning words.","Speech is always clearer than gestures.","Words are the only thing that matters.","Body language should be ignored."],"explanation":"末段 ''learning to read bodies is just as useful as learning new words'' 的转述。"}]'::jsonb, '[{"word":"interaction","cn":"交流"},{"word":"vary","cn":"变化"},{"word":"appropriate","cn":"合适的"}]'::jsonb, 2, 'elective1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'One Gesture, Many Meanings', 'The simple gesture for "OK" shows how the same sign can carry very different meanings around the world. In English-speaking countries, joining the thumb and first finger into a circle usually means that everything is fine. Yet someone who employs this gesture in Japan might think it stands for money. In France, a person who sees an identical sign may read it as the number zero, meaning "worthless". In Brazil and Germany, by contrast, the gesture is considered rude, so visitors are advised to avoid making it there. Even the movements for "yes" and "no" are not fixed. In most countries, nodding means "yes" and shaking the head means "no"; but in Bulgaria and parts of Albania, these have the opposite meaning. Because of such differences, a gesture that seems perfectly polite at home can cause real confusion abroad. The safest rule is to watch local people and follow what they do.', 'Body Language', 152, '[{"q":"What might the \"OK\" gesture mean to someone in Japan?","answer":"B","options":["That everything is fine.","Money.","The number zero.","Something rude."],"explanation":"原文 ''might think it stands for money''(日本)的转述。"},{"q":"Why should visitors avoid the gesture in Brazil and Germany?","answer":"C","options":["It means money there.","It means zero there.","It is seen as rude there.","It has no meaning there."],"explanation":"原文 ''considered rude, so visitors are advised to avoid'' 的转述。"},{"q":"What is special about \"yes\" and \"no\" in Bulgaria and parts of Albania?","answer":"D","options":["Nobody uses nodding there.","Only words are used there.","Nodding is forbidden there.","The head movements carry the reverse meaning."],"explanation":"原文 ''these have the opposite meaning'' 的转述。"}]'::jsonb, '[{"word":"employ","cn":"使用"},{"word":"identical","cn":"相同的"},{"word":"by contrast","cn":"相比之下"}]'::jsonb, 2, 'elective1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'The Power of Eye Contact', 'Where we look, and for how long, sends a strong silent message. In many Western countries, making eye contact is a way to display interest and honesty. A speaker who never meets your eyes may be thought shy or even untrustworthy. However, the rules are not the same everywhere. In some Middle Eastern countries, men and women are not socially permitted to look directly at each other for long. In Japan, lowering the eyes when talking to an older person can demonstrate respect rather than weakness. Time matters too: a friendly glance can become a hard stare if it lasts too long, and a long stare may be read as a threat. Because eye contact is understood so differently, the same look can be polite in one place and rude in another. Travellers who take a moment to learn the local habits can avoid many awkward misunderstandings.', 'Body Language', 147, '[{"q":"In many Western countries, what does eye contact often show?","answer":"A","options":["Interest and honesty.","Anger and fear.","Shyness only.","A lack of respect."],"explanation":"原文 ''a way to display interest and honesty'' 的转述。"},{"q":"Why might a Japanese person lower their eyes with an elder?","answer":"B","options":["To show they are bored.","To show respect.","Because they cannot see.","To start an argument."],"explanation":"原文 ''lowering the eyes… can demonstrate respect'' 的转述。"},{"q":"What can happen if eye contact lasts too long?","answer":"C","options":["It becomes a sign of honesty.","It always shows friendship.","It can seem threatening to the other person.","It means nothing at all."],"explanation":"原文 ''a long stare may be read as a threat'' 的转述。"}]'::jsonb, '[{"word":"display","cn":"显示"},{"word":"demonstrate","cn":"表达"},{"word":"stare","cn":"凝视"}]'::jsonb, 2, 'elective1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Why a Smile Matters', 'Of all the messages our bodies send, perhaps none is as powerful as the smile. A smile can help us get through difficult moments and find friends in a world of strangers. We can use it to apologise, to greet someone, to ask for help, or simply to start a conversation. Best of all, a smile often breaks down barriers that words cannot. Yet not every smile is honest. A fake smile may be worn to hide anger, fear or worry, and it can be hard to tell apart from a real one. Scientists say that a true smile usually reaches the eyes, making them shine, while a polite, fake smile uses only the mouth. Some experts even suggest smiling at yourself in the mirror to feel happier and stronger. So the next time you feel down or lonely, remember that there is little better than seeing the warm, honest smile of a good friend.', 'Body Language', 155, '[{"q":"According to the passage, what can a smile do that words sometimes cannot?","answer":"D","options":["Make people forget everything.","Replace all spoken language.","Cause serious arguments.","Break down barriers between people."],"explanation":"原文 ''breaks down barriers that words cannot'' 的转述。"},{"q":"Why might someone wear a fake smile?","answer":"A","options":["To hide feelings such as anger or worry.","To learn a new language.","To show they are very tired.","To copy a friend exactly."],"explanation":"原文 ''worn to hide anger, fear or worry'' 的转述。"},{"q":"How can you often tell a true smile from a fake one?","answer":"B","options":["A true smile is always silent.","A true smile reaches the eyes and makes them shine.","A fake smile uses the whole face.","A fake smile lasts much longer."],"explanation":"原文 ''a true smile usually reaches the eyes… while a polite, fake smile uses only the mouth'' 的转述。"}]'::jsonb, '[{"word":"break down","cn":"打破"},{"word":"fake","cn":"假的"},{"word":"barrier","cn":"障碍"}]'::jsonb, 2, 'elective1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'How a Teacher Reads a Class', 'In a classroom of more than forty students, a teacher cannot have a long talk with each person every day. So how does a teacher know what is going on in young minds? The answer is body language. It is easy to see when students are interested: they look up, lean slightly forward and make eye contact. People have a tendency to lean towards whatever interests them. If a student keeps looking down at his watch, it implies he is bored and counting the minutes. Two friends leaning their heads together are probably writing notes to each other. Trouble is harder to perceive. Students who are angry or anxious may cross their arms in front of their chests, as if guarding their bodies. Those who are sad often wear a frown or hide their faces in their hands. By watching these quiet signs, a caring teacher knows when to make a joke, when to slow down, and when to talk to a student alone.', 'Body Language', 164, '[{"q":"How does a teacher know students are interested?","answer":"C","options":["They hide their faces in their hands.","They cross their arms tightly.","They sit up, lean towards the teacher and meet her eyes.","They keep staring at their watches."],"explanation":"原文 ''they look up, lean slightly forward and make eye contact'' 的转述。"},{"q":"What may crossed arms in front of the chest suggest?","answer":"D","options":["The student is very interested.","The student is writing notes.","The student is leaving soon.","The student feels angry or anxious."],"explanation":"原文 ''angry or anxious may cross their arms… as if guarding their bodies'' 的转述。"},{"q":"Why does the teacher watch these quiet signs?","answer":"A","options":["To judge when to add humour, ease off or speak with a student privately.","To punish bored students.","To end the class early.","To choose the best-dressed student."],"explanation":"末句 ''knows when to make a joke, when to slow down, and when to talk to a student alone'' 的转述。"}]'::jsonb, '[{"word":"tendency","cn":"倾向"},{"word":"imply","cn":"暗示"},{"word":"perceive","cn":"察觉"}]'::jsonb, 2, 'elective1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Can a Pose Change How You Feel?', 'We all know that our feelings shape our bodies. When we feel proud and powerful, we usually straighten up to make ourselves bigger; when we feel powerless, we tend to slump and make ourselves smaller. But scientists have asked a surprising question: can our bodies also change our minds? In several experiments, people were asked to hold a strong, open pose for a couple of minutes before a stressful task. Afterwards, many of them reported feeling more confident and less afraid. It seems that standing tall, with the head up and shoulders back, can actually help push away feelings of shyness. For this reason, some scientists suggest trying "power posing" before an exam or a speech. The idea is simple but useful: if you act powerful with your body, your mind may slowly begin to believe it. So body language is not only a window into our feelings, but also a tool we can use to shape them.', 'Body Language', 158, '[{"q":"What do people usually do when they feel powerless?","answer":"B","options":["Straighten up to look bigger.","Slump and make themselves smaller.","Smile at the mirror.","Cross the room quickly."],"explanation":"原文 ''feel powerless, we tend to slump and make ourselves smaller'' 的转述。"},{"q":"What did many people report after holding a strong pose?","answer":"C","options":["They felt more tired.","They felt nothing different.","They became more sure of themselves and less fearful.","They forgot the task."],"explanation":"原文 ''feeling more confident and less afraid'' 的转述。"},{"q":"What is the main idea of \"power posing\"?","answer":"D","options":["Sitting quietly is always best.","Feelings can never change behaviour.","Body language has no real use.","Acting powerful with the body may help the mind feel powerful."],"explanation":"原文 ''if you act powerful with your body, your mind may slowly begin to believe it'' 的转述。"}]'::jsonb, '[{"word":"slump","cn":"垂头弯腰"},{"word":"pose","cn":"姿势"},{"word":"confident","cn":"自信的"}]'::jsonb, 2, 'elective1', 'U4');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U4', 'Learning to Read Faces', 'When I was young, I thought we only communicated with (1)____. Then a teacher taught me that our faces and hands send messages too. She showed us how a (2)____ frown can mean a person is unhappy, even if they say they are fine. At first I found it hard to (3)____ a real smile from a fake one. But slowly I began to (4)____ small signs that I had missed before. I learned that people often (5)____ their true feelings without meaning to. A friend who keeps looking at the door may be (6)____, while one who leans towards you is usually (7)____. Reading these quiet signs has changed the way I (8)____ with others. Now, before I speak, I take a moment to (9)____ what a person''s body is telling me. This new skill has made me a much better (10)____ to my friends.', 146, 2, '[{"q":"1","answer":"A","options":["words","prices","songs","machines"],"explanation":"communicate with words 用言语交流。"},{"q":"2","answer":"B","options":["loud","slight","rich","wet"],"explanation":"a slight frown 轻微的皱眉。"},{"q":"3","answer":"C","options":["sell","throw","distinguish","lose"],"explanation":"distinguish A from B 区分。"},{"q":"4","answer":"D","options":["forget","hide","drop","notice"],"explanation":"notice small signs 注意到细小信号。"},{"q":"5","answer":"A","options":["reveal","count","sell","wash"],"explanation":"reveal feelings 流露感受。"},{"q":"6","answer":"B","options":["happy","bored","proud","polite"],"explanation":"看门=想离开,故 bored 无聊。"},{"q":"7","answer":"C","options":["asleep","angry","interested","absent"],"explanation":"leans towards you → interested 感兴趣。"},{"q":"8","answer":"D","options":["argue","fight","sleep","interact"],"explanation":"interact with others 与人交往。"},{"q":"9","answer":"A","options":["perceive","waste","lose","break"],"explanation":"perceive what the body is telling 察觉身体的信息。"},{"q":"10","answer":"B","options":["stranger","friend","enemy","machine"],"explanation":"a better friend 更好的朋友。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U4', 'A Gesture That Went Wrong', 'On my first trip abroad, a small hand (1)____ taught me a big lesson. After a nice meal, I made the "OK" sign to the cook to show that the food was (2)____. To my surprise, he suddenly looked (3)____ and turned away. My local friend later explained that in that country the sign was very (4)____. "The same gesture can (5)____ from place to place," she said. "You should always (6)____ making it until you know the local habits." I felt (7)____ for upsetting the cook, so the next day I went back to (8)____ what I really meant. This time I simply smiled and gave a thumbs-up, and he smiled (9)____. From that day on, I have been careful to (10)____ what each gesture means before I use it in a new country.', 135, 2, '[{"q":"1","answer":"C","options":["price","song","gesture","garden"],"explanation":"a hand gesture 手势。"},{"q":"2","answer":"D","options":["wrong","empty","cold","great"],"explanation":"food was great 食物很棒。"},{"q":"3","answer":"A","options":["angry","happy","calm","sleepy"],"explanation":"turned away → angry 生气。"},{"q":"4","answer":"B","options":["polite","rude","cheap","useful"],"explanation":"the sign was rude 这手势无礼。"},{"q":"5","answer":"C","options":["sell","sleep","differ","weep"],"explanation":"differ from place to place 因地而异。"},{"q":"6","answer":"D","options":["enjoy","finish","practise","avoid"],"explanation":"avoid making it 避免做这手势。"},{"q":"7","answer":"A","options":["sorry","proud","rich","brave"],"explanation":"feel sorry 感到抱歉。"},{"q":"8","answer":"B","options":["hide","clarify","forget","lose"],"explanation":"clarify what I meant 澄清我的意思。"},{"q":"9","answer":"C","options":["down","away","back","off"],"explanation":"smiled back 回以微笑。"},{"q":"10","answer":"D","options":["sell","drop","break","learn"],"explanation":"learn what each gesture means 弄清含义。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U4', 'Buying Beef Without Words', 'My grandmother once told me a funny story about (1)____ in America. She did not speak much English, so shopping was a real (2)____ for her. One day she went to buy some beef, but there were so many kinds of (3)____ that she did not know which to choose. She could not (4)____ the words to a clerk, so she had an idea. She put both hands up like horns and said, "Moo! Moo!" The clerk laughed, but he understood her at once and (5)____ her to the beef. Grandmother got exactly what she (6)____ without saying a single English word. This little (7)____ showed her that acting can help people (8)____ even across a language gap. "When words fail," she often says, "your body can still (9)____ the message." Now I am never (10)____ to use my hands when I travel somewhere new.', 145, 2, '[{"q":"1","answer":"A","options":["living","selling","sleeping","weeping"],"explanation":"living in America 在美国生活(动名词作介词宾语)。"},{"q":"2","answer":"B","options":["holiday","struggle","game","song"],"explanation":"a real struggle 一种艰难。"},{"q":"3","answer":"C","options":["prices","noises","meat","weather"],"explanation":"kinds of meat 各种肉。"},{"q":"4","answer":"D","options":["throw","sell","lose","explain"],"explanation":"explain the words 说清意思。"},{"q":"5","answer":"A","options":["led","sold","hid","lost"],"explanation":"led her to the beef 把她领到牛肉处。"},{"q":"6","answer":"B","options":["dropped","wanted","feared","broke"],"explanation":"what she wanted 她想要的。"},{"q":"7","answer":"C","options":["price","noise","incident","garden"],"explanation":"this little incident 这件小事。"},{"q":"8","answer":"D","options":["argue","fail","sleep","communicate"],"explanation":"help people communicate 帮人交流。"},{"q":"9","answer":"A","options":["carry","lose","hide","waste"],"explanation":"carry the message 传递信息。"},{"q":"10","answer":"B","options":["glad","afraid","proud","sure"],"explanation":"never afraid to use 从不害怕用手势。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U4', 'The Body of a Shy Student', 'Lin was one of the shyest students in our (1)____. While others raised their hands, he often kept his head (2)____ and his eyes on the desk. When the teacher asked a question, he would (3)____ his arms tightly, as if guarding himself. At first, the teacher thought Lin was simply (4)____ in the lesson. But she watched his body language more carefully and began to (5)____ that he was actually afraid of being (6)____ on. Instead of forcing him to speak, she gave him time and spoke to him (7)____ after class. Slowly, Lin started to (8)____ up his posture and even made a little eye contact. By the end of term, he could (9)____ a short answer in front of everyone without panicking. His changing body told the whole story: a frightened boy had (10)____ into a more confident young man.', 143, 2, '[{"q":"1","answer":"C","options":["price","song","class","market"],"explanation":"in our class 在班上。"},{"q":"2","answer":"D","options":["up","rich","wet","lowered"],"explanation":"head lowered 低着头。"},{"q":"3","answer":"A","options":["cross","sell","drop","lose"],"explanation":"cross his arms 交叉双臂。"},{"q":"4","answer":"B","options":["interested","uninterested","proud","loud"],"explanation":"低头看桌→ uninterested 不感兴趣(后文转折)。"},{"q":"5","answer":"C","options":["sell","forget","perceive","throw"],"explanation":"perceive that 察觉到。"},{"q":"6","answer":"D","options":["sold","washed","lost","called"],"explanation":"be called on 被点名。"},{"q":"7","answer":"A","options":["gently","loudly","angrily","rudely"],"explanation":"spoke to him gently 温和地对他说。"},{"q":"8","answer":"B","options":["break","straighten","sell","lose"],"explanation":"straighten up his posture 挺直身姿。"},{"q":"9","answer":"C","options":["hide","drop","give","throw"],"explanation":"give a short answer 给出简短回答。"},{"q":"10","answer":"D","options":["fallen","broken","lost","grown"],"explanation":"grown into 成长为。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U4', 'Greetings Around the World', 'People all over the world say hello, but they do it in many different (1)____. In France and Russia, friends often kiss each other on the (2)____ when they meet. In Japan, by (3)____, people usually bow from the waist as a sign of (4)____. In many Western countries, a firm handshake is the most common way to (5)____ someone. Some cultures (6)____ a gentle nod of the head, while others give a warm hug. None of these is right or (7)____; they are simply different habits. A traveller who learns the local greeting can quickly (8)____ down the wall between strangers. Using the wrong one, on the other hand, may cause a small (9)____. So before you visit a new country, it is wise to find out how the people there like to be (10)____.', 136, 2, '[{"q":"1","answer":"A","options":["ways","prices","songs","machines"],"explanation":"in different ways 用不同方式。"},{"q":"2","answer":"B","options":["foot","cheek","wall","road"],"explanation":"kiss on the cheek 吻脸颊。"},{"q":"3","answer":"C","options":["price","noise","contrast","weather"],"explanation":"by contrast 相比之下。"},{"q":"4","answer":"D","options":["anger","fear","noise","respect"],"explanation":"a sign of respect 尊重的标志。"},{"q":"5","answer":"A","options":["greet","sell","lose","hide"],"explanation":"greet someone 问候某人。"},{"q":"6","answer":"B","options":["fear","favour","lose","break"],"explanation":"favour a nod 偏爱点头。"},{"q":"7","answer":"C","options":["deep","wide","wrong","late"],"explanation":"right or wrong 对或错。"},{"q":"8","answer":"D","options":["sell","drop","throw","break"],"explanation":"break down the wall 打破隔阂。"},{"q":"9","answer":"A","options":["misunderstanding","song","price","garden"],"explanation":"a small misunderstanding 小误会。"},{"q":"10","answer":"B","options":["sold","greeted","lost","hidden"],"explanation":"like to be greeted 喜欢被问候。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U4', 'A Test About Smiling', 'Our science teacher once gave us a simple (1)____ about smiling. She asked half the class to hold a wide smile for two minutes, while the other half kept their faces (2)____. Then we all did a short, difficult task. Afterwards, the students who had been (3)____ said they felt calmer and more (4)____ than the others. "Your body can change how your mind (5)____," the teacher explained. "If you act happy, you may slowly begin to (6)____ happier." She added that a true smile (7)____ down barriers and makes other people trust you. Of course, a (8)____ smile, used only to hide worry, does not have the same power. The lesson (9)____ a strong message on all of us: a real smile is not just polite, it is a useful (10)____ that can lift both your own mood and the mood of those around you.', 146, 2, '[{"q":"1","answer":"C","options":["price","song","test","garden"],"explanation":"a simple test 一个简单测试。"},{"q":"2","answer":"D","options":["loud","rich","wet","still"],"explanation":"kept their faces still 面部不动。"},{"q":"3","answer":"A","options":["smiling","selling","sleeping","weeping"],"explanation":"had been smiling 一直微笑(动名词)。"},{"q":"4","answer":"B","options":["afraid","confident","bored","angry"],"explanation":"more confident 更自信。"},{"q":"5","answer":"C","options":["sells","breaks","feels","loses"],"explanation":"how your mind feels 心情如何。"},{"q":"6","answer":"D","options":["sell","lose","drop","feel"],"explanation":"feel happier 感觉更快乐。"},{"q":"7","answer":"A","options":["breaks","sells","hides","loses"],"explanation":"breaks down barriers 打破隔阂。"},{"q":"8","answer":"B","options":["real","fake","loud","rich"],"explanation":"a fake smile 假笑。"},{"q":"9","answer":"C","options":["sold","lost","left","broke"],"explanation":"left a message 留下信息。"},{"q":"10","answer":"D","options":["price","noise","garden","tool"],"explanation":"a useful tool 有用的工具。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·对话 Gestures Around the World', '选择性必修一 U4 · dialogue', 3, 'Mia: Tom, I made the "OK" sign to a waiter in France and he looked upset. Why?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·短文 The Power of a Smile', '选择性必修一 U4 · passage', 2, 'A smile may be the most powerful piece of body language we have.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·对话 Learning Silent Acting', '选择性必修一 U4 · dialogue', 3, 'Ben: How are your acting classes going? I heard you act without speaking.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·短文 Reading a Classroom', '选择性必修一 U4 · passage', 2, 'As a teacher, I learn a lot just by watching my students'' bodies.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·对话 Asking for Clarification', '选择性必修一 U4 · dialogue', 3, 'Anna: You looked at your watch during my talk. What did you mean by that?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U4 听力·短文 Tips for Travellers', '选择性必修一 U4 · passage', 2, 'Here are a few simple tips about body language for travellers.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (11, 'Write about Body Language across Cultures(写一篇关于跨文化肢体语言的短文)', 'Write about Body Language across Cultures(写一篇关于跨文化肢体语言的短文)', '假设你叫李华,你的英国笔友 Chris 下个月将第一次来中国。请用英语写一篇约80词的短文,内容包括:① 说明肢体语言因文化而异(举一两个例子,如手势/眼神/问候);② 给 Chris 一两条在中国得体使用肢体语言的建议;③ 表达欢迎他来的心情。注意:句子围绕中心、地道连贯。', 'Suppose you are Li Hua. Your British pen-friend Chris will visit China for the first time next month. Write a short passage (about 80 words) including: 1) explain that body language varies from culture to culture, with one or two examples (gestures, eye contact, greetings); 2) one or two pieces of advice for using body language politely in China; 3) say that you welcome his visit.', '["说明肢体语言因文化而异(Body language varies from culture to culture)","举例(For example, the same gesture may mean … / eye contact …)","给出得体建议(My advice is … / You''d better avoid …)","表达欢迎(I look forward to seeing you in China!)"]'::jsonb, 70, 100, 'Dear Chris, I''m so glad you''re coming to China next month! One thing worth knowing is that body language varies from culture to culture. For example, a gesture that is friendly at home may mean something different here, and staring at someone too long can be read as rude. My advice is simple: watch how local people behave, keep your eye contact polite, and a warm smile is always welcome. Don''t worry about small mistakes — we''ll all understand. I really look forward to seeing you and showing you around!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Body language varies from culture to culture.","A gesture that is friendly at home may mean something quite different here.","Watch how local people behave, and keep your eye contact polite.","A warm smile is always welcome almost everywhere."]'::jsonb, '[{"wrong":"I look forward to see you.","correct":"I look forward to seeing you.","note":"look forward to 中 to 是介词,后接动名词。"},{"wrong":"The gesture mean different things.","correct":"The gesture means different things.","note":"主语第三人称单数,动词加 s。"},{"wrong":"Avoid to stare at people.","correct":"Avoid staring at people.","note":"avoid 后接动名词,不接不定式。"}]'::jsonb, '【跨文化肢体语言短文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (11, 'elective1', 'U4', '{"title":"动名词(-ing)作宾语和表语 速查","intro":"动名词(动词 + ing)兼具动词和名词的性质,可作宾语(动词宾语 / 介词宾语)和表语。判断口诀:某些动词与所有介词后,跟动作要用动名词(doing),不用不定式(to do)或原形。","table":{"headers":["功能","用法 / 例句"],"rows":[["作动词宾语","enjoy/finish/mind/avoid/keep/practise/suggest/consider/imagine/can''t help + doing:She enjoys learning body language."],["作介词宾语","介词(at/in/of/for/about/on/to)+ doing:be good at reading faces;look forward to learning"],["作表语","be + doing,说明主语内容:My job is teaching. / Seeing is believing."],["对比 to do","want/hope/decide/plan/would like + to do(这些动词后用不定式,不用动名词)"]]},"specialRules":[{"rule":"look forward to / be(get) used to / instead of 里的 to 是介词,后接动名词","mark":"look forward to seeing(× to see)"},{"rule":"enjoy/finish/mind/avoid/keep/practise/suggest/consider/can''t help 后只接动名词","mark":"avoid making the gesture(× to make)"},{"rule":"动名词作表语 ≈ 主语内容的等价说明,主表常可互换","mark":"My job is teaching = Teaching is my job"},{"rule":"区分:be doing 作表语(说明主语) vs be doing 作进行时(强调动作正在进行)","mark":"His hobby is fishing(表语)/ He is fishing now(进行时)"}],"why":["介词是\"接名词性成分\"的词,而动名词正是动词的名词形式,所以介词后、以及部分及物动词后,要把动作变成 doing 才能作宾语;作表语时,动名词同样以名词身份说明主语\"是什么/做什么\"。"],"gaokaoPoints":["高频考点:enjoy/avoid/mind/finish/suggest/consider/practise/keep/can''t help + doing 的固定搭配。","易错点:look forward to / be used to / instead of / devote…to 里的 to 是介词,后接 doing,不是动词原形;语法填空与改错高频。"],"examVsReal":[{"exam":"I look forward to hearing from you.（考试/书面）","real":"Can''t wait to hear from you!","note":"考试用 look forward to + doing;口语常换成 can''t wait to do"},{"exam":"My job is teaching English.（表语,考试标准）","real":"I teach English.","note":"考试爱考动名词作表语;口语里直接用动词更自然"}]}'::jsonb);
